def format_bytes(n):
    """Return a human‑readable size for a byte count."""
    if n == 0:
        return '0 B'
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    size = float(n / 1024.0)
    i = int(size.bit_length() - 1)
    factor = 1024.0 ** (1 - i)
    return f'{size:.1f} {factor:.0f} {units[i]}'

